def compute(vars):
    values = {
        "v1": vars["v1"],
        "v2": vars["v2"],
        "v3": vars["v3"],
        "v4": vars["v4"],
        "v5": vars["v5"],
        "v6": vars["v6"],
    }
    result = sum(values.values())
    return {
        "value": result,
        "trace": {
            "inputs": values,
            "sum": result,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None,
            },
        },
    }
